package com.yuegang.zhihui.search.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.search.api.*;import com.yuegang.zhihui.search.infrastructure.*;import java.util.*;import org.springframework.jdbc.core.*;import org.springframework.web.client.RestClient;
public final class HybridSearchService{private final JdbcTemplate jdbc;private final RestClient elastic;private final DoubaoEmbeddingGateway embeddings;private final String alias;public HybridSearchService(JdbcTemplate j,String es,DoubaoEmbeddingGateway e,String a){jdbc=j;elastic=RestClient.builder().baseUrl(es).build();embeddings=e;alias=a;}public List<SearchHit>search(SearchRequest r){List<Double>vector=embeddings.embed(r.query());String literal=vector.toString();var vectorHits=jdbc.query("SELECT document_id,chunk_id,1-(embedding <=> ?::vector) score FROM search_embedding WHERE index_version=(SELECT active_version FROM search_index_version WHERE alias_name=?) ORDER BY embedding <=> ?::vector LIMIT ?",(x,n)->new Raw(x.getString(1),x.getString(2),"","",0,x.getDouble(3)),literal,alias,literal,r.limit()*2);Map<?,?>body=elastic.post().uri("/"+alias+"/_search").body(Map.of("size",r.limit()*2,"query",Map.of("bool",Map.of("must",List.of(Map.of("multi_match",Map.of("query",r.query(),"fields",List.of("title^3","content")))),"filter",r.category()==null?List.of():List.of(Map.of("term",Map.of("category",r.category()))))))).retrieve().body(Map.class);var lexical=parse(body);var merged=new LinkedHashMap<String,Raw>();int rank=1;for(var h:lexical){double rrf=1d/(60+rank++);merged.put(h.key(),h.withLexical(rrf));}rank=1;for(var h:vectorHits){double rrf=1d/(60+rank++);merged.merge(h.key(),h.withVector(rrf),(a,b)->a.merge(b));}return merged.values().stream().sorted(Comparator.comparingDouble(Raw::finalScore).reversed()).limit(r.limit()).map(x->new SearchHit(x.document,x.chunk,x.title,excerpt(x.content),x.lexical,x.vector,x.finalScore())).toList();}public void index(IndexChunkCommand c){if(!c.published())throw new BusinessException(ErrorCode.PERMISSION_DENIED);var vector=embeddings.embed(c.content());jdbc.update("INSERT INTO search_embedding(document_id,chunk_id,index_version,visibility,embedding,content_sha256) VALUES(?,?,?, ?,?::vector,encode(sha256(?::bytea),'hex')) ON CONFLICT(document_id,chunk_id,index_version) DO UPDATE SET embedding=EXCLUDED.embedding,visibility=EXCLUDED.visibility",Long.parseLong(c.documentId()),Long.parseLong(c.chunkId()),c.indexVersion(),c.visibility(),vector.toString(),c.content().getBytes(java.nio.charset.StandardCharsets.UTF_8));elastic.put().uri("/"+c.indexVersion()+"/_doc/"+c.chunkId()).body(Map.of("documentId",c.documentId(),"chunkId",c.chunkId(),"title",c.title(),"content",c.content(),"category",c.category(),"visibility",c.visibility())).retrieve().toBodilessEntity();}private static List<Raw>parse(Map<?,?>body){if(body==null)return List.of();var hits=(Map<?,?>)body.get("hits");if(hits==null)return List.of();var rows=(List<?>)hits.get("hits");if(rows==null)return List.of();var out=new ArrayList<Raw>();for(Object o:rows){var row=(Map<?,?>)o;var src=(Map<?,?>)row.get("_source");out.add(new Raw(Objects.toString(src.get("documentId")),Objects.toString(src.get("chunkId")),Objects.toString(src.get("title")),Objects.toString(src.get("content")),((Number)row.get("_score")).doubleValue(),0));}return out;}private static String excerpt(String s){return s.length()<=300?s:s.substring(0,300);}private record Raw(String document,String chunk,String title,String content,double lexical,double vector){String key(){return document+":"+chunk;}Raw withLexical(double s){return new Raw(document,chunk,title,content,s,vector);}Raw withVector(double s){return new Raw(document,chunk,title,content,lexical,s);}Raw merge(Raw b){return new Raw(document,chunk,title.isBlank()?b.title:title,content.isBlank()?b.content:content,lexical+b.lexical,vector+b.vector);}double finalScore(){return lexical+vector;}}}
